/**
 * A small curated panel of very common plasmid features, used to auto-annotate
 * a bare sequence (FASTA / raw paste) that arrives without annotations. These
 * are the sequences most cloning vectors share (resistance markers, origins,
 * common promoters and primer sites). Detection is exact substring match on
 * either strand — cheap and precise, if not exhaustive.
 */
export interface CommonFeature {
  name: string;
  type: string;
  bp: string;
}

